from seven_desks.settings import CACHE as BUILD_ROOT, LAKE, SOURCE as REVIEW_SOURCE, FROZEN_VERSION
from seven_desks.store import version_root, connect
"""Rebuild application-local ownership enrichments from corrected aggregates."""
from pathlib import Path
import duckdb,json
P=Path(__file__).resolve().parents[2]; O=(BUILD_ROOT / 'ac-fix'); L=(BUILD_ROOT / 'owners'); S=(REVIEW_SOURCE / 'owners')
c=connect(config={'threads':2,'memory_limit':'4GB'})
for directory,prefix in [(S,'s_'),(L,'l_'),(O,'x_')]:
 for p in directory.glob('*.parquet'):
  if not p.name.startswith(('_','tmp_')):c.execute(f"CREATE VIEW {prefix+p.stem} AS SELECT * FROM '{p}'")
def emit(n,sql):
 c.execute(f"COPY ({sql}) TO '{O/n}.parquet' (FORMAT PARQUET,COMPRESSION ZSTD)")
 c.execute(f"CREATE OR REPLACE VIEW x_{n} AS SELECT * FROM '{O/n}.parquet'")
 print(n,flush=True)
def mid(v):
 return f"CASE WHEN {v} IS NOT NULL THEN (rank() OVER(PARTITION BY report_period,({v} IS NOT NULL) ORDER BY {v})-1+0.5*count(*) OVER(PARTITION BY report_period,{v}))/count(*) OVER(PARTITION BY report_period,({v} IS NOT NULL)) END"
emit('company_rank_complete',"""SELECT p.*,p.visible_market_value-prev.visible_market_value period_value_change,a.net_assets,a.stock_allocation,p.visible_market_value/nullif(a.net_assets,0) holding_nav_ratio,o.net_asset_coverage,o.mean_visible_halfyears,o.return_1y,o.return_2y,o.weighted_return_1y,o.excess_1y,i.implied_return,coalesce(a.asset_denominator_status,'missing_asset_snapshot') asset_denominator_status FROM x_company_period p JOIN l_company_rank_complete o USING(company_id,report_period) LEFT JOIN x_company_asset_snapshot a USING(company_id,report_period) LEFT JOIN x_company_implied_halfyear_return i USING(company_id,report_period) LEFT JOIN x_company_period prev ON prev.company_id=p.company_id AND prev.report_period=last_day(p.report_period-INTERVAL '6 months')""")
emit('company_holding_complete',"""SELECT h.*,o.name,c.change_status,c.share_change_ratio,c.estimated_change_value,o.consecutive_halfyears,h.weight-b.weight influence_pp,o.post_period_return FROM x_company_stock_holdings h JOIN l_company_holding_complete o USING(company_id,report_period,symbol) LEFT JOIN x_company_changes c ON c.entity_id=h.company_id AND c.report_period=h.report_period AND c.symbol=h.symbol LEFT JOIN x_company_stock_holdings b ON b.company_id=h.company_id AND b.symbol=h.symbol AND b.report_period=last_day(h.report_period-INTERVAL '6 months')""")
emit('fund_industry_market',"""WITH f AS(SELECT report_period,industry_code,max(industry_name) industry_name,sum(market_value) market_value,count(DISTINCT company_id) company_count,sum(stock_count) company_stock_observations FROM x_company_industry GROUP BY ALL),m AS(SELECT report_period,industry_code,sum(float_shares*close) float_market_value FROM s_period_stock_context GROUP BY ALL),a AS(SELECT f.*,market_value/sum(market_value) OVER(PARTITION BY report_period) weight,m.float_market_value/sum(m.float_market_value) OVER(PARTITION BY report_period) market_weight FROM f LEFT JOIN m USING(report_period,industry_code)) SELECT *,weight-market_weight overweight FROM a""")
emit('fund_industry_complete',"""WITH changes AS(SELECT c.report_period,s.industry_code,sum(c.estimated_change_value) estimated_net_change FROM x_company_changes c LEFT JOIN s_period_stock_context s USING(symbol,report_period) WHERE c.change_status IN('new_visible','increase','decrease','exit_visible','unchanged') GROUP BY ALL) SELECT h.*,h.weight-p.weight weight_change,ch.estimated_net_change FROM x_fund_industry_market h LEFT JOIN x_fund_industry_market p ON p.industry_code=h.industry_code AND p.report_period=last_day(h.report_period-INTERVAL '6 months') LEFT JOIN changes ch ON ch.report_period=h.report_period AND ch.industry_code=h.industry_code""")
emit('fund_band_complete',"""SELECT report_period,size_band,count(*) company_count,sum(visible_market_value) market_value,sum(fund_count) fund_count,sum(estimated_net_change) estimated_change_value,sum(new_count) new_count,sum(increase_count) increase_count,sum(decrease_count) decrease_count,sum(exit_count) exit_count FROM x_company_rank_complete GROUP BY ALL""")
emit('fund_band',"SELECT report_period,size_band,count(*) company_count,sum(visible_market_value) market_value,sum(fund_count) fund_count,sum(estimated_net_change) estimated_change_value FROM x_company_period GROUP BY ALL")
emit('fund_market_history',"""WITH a AS(SELECT report_period,count(*) company_count,sum(visible_market_value) market_value,sum(fund_count) share_class_count,sum(new_count) new_count,sum(increase_count) increase_count,sum(decrease_count) decrease_count,sum(exit_count) exit_count,sum(estimated_net_change) estimated_change_value FROM x_company_period GROUP BY ALL),b AS(SELECT report_period,count(*) stock_count FROM x_fund_stock_crowding GROUP BY ALL) SELECT * FROM a LEFT JOIN b USING(report_period)""")
emit('fund_stock_score',f"""WITH ranks AS(SELECT a.report_period,a.symbol,count(*) FILTER(WHERE a.holding_rank<b.holding_rank) rank_risers,count(*) FILTER(WHERE a.holding_rank<=10 AND coalesce(b.holding_rank,999999)>10) top10_entrants FROM x_company_stock_holdings a LEFT JOIN x_company_stock_holdings b ON a.company_id=b.company_id AND a.symbol=b.symbol AND b.report_period=last_day(a.report_period-INTERVAL '6 months') WHERE month(a.report_period) IN(6,12) GROUP BY ALL),base AS(SELECT f.*,coalesce(r.rank_risers,0) rank_risers,coalesce(r.top10_entrants,0) top10_entrants FROM x_fund_stock_crowding f LEFT JOIN ranks r USING(report_period,symbol) WHERE f.ipo_status='eligible_preperiod_listed'),x AS(SELECT *,{mid('market_value')} value_percentile,{mid('(buyers-sellers)')} net_buyers_percentile,{mid('rank_risers')} rank_risers_percentile FROM base) SELECT *,100*(company_percentile+float_percentile+value_percentile+net_buyers_percentile+rank_risers_percentile)/5 composite_score_proxy,'approx_five_percentiles_company_float_value_netbuyers_rank;not_original_formula' score_status FROM x""")
emit('fund_heat_complete',"""WITH changes AS(SELECT report_period,symbol,count(*) FILTER(WHERE change_status='new_visible') new_count,count(*) FILTER(WHERE change_status='increase') increase_count,count(*) FILTER(WHERE change_status='decrease') decrease_count,count(*) FILTER(WHERE change_status='exit_visible') exit_count FROM x_company_changes WHERE change_status IN('new_visible','increase','decrease','exit_visible','unchanged') GROUP BY ALL) SELECT f.*,n.name,s.industry_name,s.float_shares*s.close float_market_value,c.new_count,c.increase_count,c.decrease_count,c.exit_count FROM x_fund_stock_score f LEFT JOIN changes c USING(report_period,symbol) LEFT JOIN s_period_stock_context s USING(symbol,report_period) LEFT JOIN l_names n USING(symbol)""")
emit('company_holding_universe',"""SELECT * FROM x_company_holding_complete UNION ALL BY NAME SELECT c.entity_id company_id,c.report_period,c.symbol,0.0 shares,0.0 market_value,0::BIGINT fund_count,0::BIGINT value_count,0::BIGINT row_count,NULL::DATE latest_announce,'exit_from_comparable_visible_full_holdings' disclosure_scope,c.close,s.factor,s.adjusted_close,s.price_date,s.industry_code,s.industry_name,s.float_shares,0.0 float_holding_ratio,0.0 weight,NULL::BIGINT holding_rank,'verified_comparable_visible_exit_not_actual_liquidation' quality_status,n.name,c.change_status,c.share_change_ratio,c.estimated_change_value,0::BIGINT consecutive_halfyears,-b.weight influence_pp,r.post_period_return FROM x_company_changes c LEFT JOIN s_period_stock_context s USING(symbol,report_period) LEFT JOIN x_company_stock_holdings b ON b.company_id=c.entity_id AND b.symbol=c.symbol AND b.report_period=c.prev_period LEFT JOIN l_stock_period_returns r ON r.symbol=c.symbol AND r.report_period=c.report_period LEFT JOIN l_names n ON n.symbol=c.symbol WHERE c.change_status='exit_visible'""")
emit('fund_consensus_following_complete',"""WITH x AS(SELECT f.report_period,f.consensus,f.symbol,p.adjusted_close start_price,last_day(f.report_period+INTERVAL '6 months') end_date FROM x_fund_stock_crowding f LEFT JOIN l_stock_lifetimes life USING(symbol) LEFT JOIN s_period_stock_context p USING(symbol,report_period) WHERE f.consensus IN('buy','sell') AND (life.list_date IS NULL OR life.list_date<=last_day(f.report_period-INTERVAL '6 months')) AND last_day(f.report_period+INTERVAL '6 months')<=DATE '2026-11-09'),r AS(SELECT x.*,b.adjusted_close end_price FROM x ASOF LEFT JOIN l_daily_prices b ON x.symbol=b.symbol AND x.end_date>=b.trade_date),a AS(SELECT report_period,consensus,end_date,avg(end_price/nullif(start_price,0)-1) equal_weight_following_return,count(end_price/nullif(start_price,0)) valid_price_count,count(*) signal_stock_count FROM r GROUP BY ALL),b AS(SELECT a.*,bs.close begin_benchmark FROM a ASOF LEFT JOIN l_benchmark_daily bs ON a.report_period>=bs.trade_date) SELECT b.*,be.close/nullif(begin_benchmark,0)-1 benchmark_return FROM b ASOF LEFT JOIN l_benchmark_daily be ON b.end_date>=be.trade_date""")
